using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Graph.Walks;
internal sealed class CycleDiagonalUnitPropagationDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Two adjacent standard diagonal units in the real cycle algebra force every matrix unit, scalar complex commutants, and only the two scalar orthogonal symmetries.",
        H("Diagonal units propagate around a cycle"),
        Blocks(
            Paragraph(Text("Let L be any natural number at least three, with sites in Fin L and addition taken modulo L. Let A be the ordinary simple-cycle adjacency matrix, Delta its graph Laplacian, and V = Matrix.diagonal v for an arbitrary real potential v. Every vertex has two distinct neighbours, including on the triangle, so Delta = 2I - A. Write B = Algebra.adjoin real {Delta,V}, the real unital matrix algebra generated by those two matrices. The same algebra is generated by A and V. Write E(i,k) = Matrix.single i k 1 and C(M) = M.map Complex.ofReal for the entrywise complex image of a real matrix.")),
            Describe.Lean(DescribeId.Create("cycle-diagonal-units-full"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/Walks/CycleDiagonalUnitPropagation.cycle_diagonal_units_full"),
                H("Two adjacent diagonal units imply full algebra"),
                StatementSource.FromAuthor(Statement()), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("Assume E(j,j) and E(j+1,j+1) belong to B for some cyclic site j. If E(k-1,k-1) and E(k,k) belong to B, put Q = I - E(k-1,k-1). The column A E(k,k) is E(k-1,k) + E(k+1,k), and the corresponding row is E(k,k-1) + E(k,k+1). Multiplying by Q removes the k-1 component. Hence Q A E(k,k) and E(k,k) A Q are E(k+1,k) and E(k,k+1), whose product is E(k+1,k+1). All operations remain inside the real algebra. Induction in the number of cyclic steps starting at j gives every diagonal unit, without a bound on L.")),
                    Paragraph(Text("For every graph edge from i to k, E(i,i) A E(k,k) = E(i,k). A walk from i to k exists because the cycle is connected. The successive edge units multiply to E(i,k), with the length-zero walk giving E(i,i). Thus every standard matrix unit belongs to B. Expanding an arbitrary real matrix as the finite sum of its entries times E(i,k) gives B = the full real matrix algebra.")),
                    Paragraph(Text("Entrywise complexification is a real algebra homomorphism. A complex matrix commuting with C(Delta) and C(V) therefore commutes with the image of every element of B, in particular every complex standard unit. Matrix.mem_range_scalar_iff_commute_single' gives X = cI. Applying this to the complex image of a real orthogonal O and taking real parts gives O = aI with a real. Orthogonality gives a squared equal to one, so O is I or minus I. No distinct-value, generic-potential or two-valued-potential assumption is imposed."))),
                DescribeRole.Theorem))));
    private static Formula Call(string n, params Formula[] a) =>
        new Formula.Apply(Seq(Operatorname, Grp(F.Id(n))), [..a]);
    private static Formula Par(Formula x) => Seq(Open, x, Close);
    private static Formula All(string n, Formula t, Formula b) =>
        Seq(Forall, Sp, Par(Seq(F.Id(n), Sp, Colon, Sp, t)), Comma, Sp, b);
    private static Formula Ex(string n, Formula t, Formula b) =>
        Seq(Exists, Sp, Par(Seq(F.Id(n), Sp, Colon, Sp, t)), Comma, Sp, b);
    private static Formula Rel(Formula x, FormulaRelationOperator o, Formula y) => new Formula.Relation(x,o,y);
    private static Formula Eq(Formula x, Formula y) => Rel(x, FormulaRelationOperator.Equal,y);
    private static Formula Logic(Formula x, FormulaLogicOperator o, Formula y) => new Formula.Logic(Par(x),o,Par(y));
    private static Formula And(Formula x, Formula y) => Logic(x,FormulaLogicOperator.And,y);
    private static Formula Imp(Formula x, Formula y) => Logic(x,FormulaLogicOperator.Implies,y);
    private static Formula Field(string n) => Seq(Mathbb,Grp(F.Id(n)));
    private static Formula Sites => Call("Fin",F.Id("L"));
    private static Formula Mat(string f) => Call("Matrix",Sites,Sites,Field(f));
    private static Formula Member(Formula x, Formula y) => Rel(x,FormulaRelationOperator.MemberOf,y);
    private static Formula Unit(Formula i, Formula k) => Call("E",i,k);
    private static Formula Scalar(Formula c) => Seq(c,Sp,Cdot,Sp,F.Id("I"));
    private static Formula Statement()
    {
        Formula j=F.Id("j"), jp=new Formula.Binary(j,FormulaBinaryOperator.Add,D(1));
        Formula seed=Ex("j",Sites,And(Member(Unit(j,j),F.Id("B")),Member(Unit(jp,jp),F.Id("B"))));
        Formula X=F.Id("X"), O=F.Id("O"), delta=F.Id("Delta"), V=F.Id("V");
        Formula complex=All("X",Mat("C"),Imp(Call("Commute",X,Call("C",delta)),
            Imp(Call("Commute",X,Call("C",V)),Ex("c",Field("C"),Eq(X,Scalar(F.Id("c")))))));
        Formula orthogonal=All("O",Mat("R"),Imp(Member(O,Call("OrthogonalGroup",Sites,Field("R"))),
            Imp(Call("Commute",O,delta),Imp(Call("Commute",O,V),
                Logic(Eq(O,F.Id("I")),FormulaLogicOperator.Or,Eq(O,new Formula.Negate(F.Id("I"))))))));
        return Disp(All("L",Field("N"),Imp(Rel(D(3),FormulaRelationOperator.LessThanOrEqual,F.Id("L")),
            All("v",new Formula.TypeArrow(Sites,Field("R")),Imp(seed,
                And(Eq(F.Id("B"),Call("FullMatrixAlgebra",Sites,Field("R"))),And(complex,orthogonal)))))));
    }
}
